import React, { useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useReactToPrint } from "react-to-print";
import {
  HeartPulse,
  Brain,
  Activity,
  AlertTriangle,
  Stethoscope,
  Lungs,
  Droplets,
  Thermometer,
  Shield,
  Smile,
  Zap,
} from "lucide-react";

export default function SuggestionPage() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const data = state?.data || {};

  const [lang, setLang] = useState(data.lang || "english");
  const details = data.symptom_details || [];
  const predictions = data.predictions || [];

  // PDF print ref
  const printRef = useRef();
  const handlePrint = useReactToPrint({
    content: () => printRef.current,
    documentTitle: "Health_Suggestions",
  });

  // Simple emoji/icon map
  const iconMap = {
    fever: <Thermometer className="inline w-5 h-5 text-red-500" />,
    cough: <Lungs className="inline w-5 h-5 text-blue-500" />,
    headache: <Brain className="inline w-5 h-5 text-purple-500" />,
    fatigue: <Zap className="inline w-5 h-5 text-yellow-500" />,
    sore_throat: <Stethoscope className="inline w-5 h-5 text-green-500" />,
    chest_pain: <HeartPulse className="inline w-5 h-5 text-pink-500" />,
    dizziness: <Activity className="inline w-5 h-5 text-orange-500" />,
    runny_nose: <Droplets className="inline w-5 h-5 text-blue-400" />,
    rash: <AlertTriangle className="inline w-5 h-5 text-rose-500" />,
    joint_pain: <Shield className="inline w-5 h-5 text-emerald-500" />,
  };

  return (
    <div className="p-6 max-w-4xl mx-auto min-h-screen bg-gradient-to-b from-white to-blue-50 rounded-xl shadow-md">
      {/* Header + Language Toggle */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">
          💡 Health Suggestions
        </h1>
        <div className="flex items-center space-x-2">
          <button
            className={`px-3 py-1 rounded-md text-sm font-medium ${
              lang === "english"
                ? "bg-blue-600 text-white"
                : "bg-gray-200 text-gray-700"
            }`}
            onClick={() => setLang("english")}
          >
            English
          </button>
          <button
            className={`px-3 py-1 rounded-md text-sm font-medium ${
              lang === "kriol"
                ? "bg-blue-600 text-white"
                : "bg-gray-200 text-gray-700"
            }`}
            onClick={() => setLang("kriol")}
          >
            Kriol
          </button>
        </div>
      </div>

      <div ref={printRef}>
        {/* Section 1: Possible Conditions */}
        <section className="mb-8">
          <h2 className="text-xl font-semibold text-gray-700 mb-2">
            🩺 Possible Conditions
          </h2>
          <div className="bg-blue-50 p-4 rounded-xl">
            {predictions.length > 0 ? (
              <ul className="list-disc pl-6 space-y-1 text-gray-700">
                {predictions.map((p, i) => (
                  <li key={i}>
                    <span className="font-medium">{p.disease}</span> —{" "}
                    {(p.score * 100).toFixed(1)}%
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600">No disease prediction available.</p>
            )}
          </div>
        </section>

        {/* Section 2: Symptoms You Mentioned */}
        <section className="mb-8">
          <h2 className="text-xl font-semibold text-gray-700 mb-4">
            🤕 Symptoms You Mentioned
          </h2>

          {details.length > 0 ? (
            details.map((sym, index) => {
              const icon = iconMap[
                sym.symptom.toLowerCase().replace(" ", "_")
              ] || <Smile className="inline w-5 h-5 text-gray-400" />;
              return (
                <div
                  key={index}
                  className="bg-white mb-4 p-4 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition"
                >
                  <h3 className="text-lg font-semibold mb-2 text-gray-800 flex items-center space-x-2">
                    <span>{icon}</span>
                    <span>
                      {sym.symptom}{" "}
                      {sym.symptom_kriol && (
                        <span className="text-gray-500 text-sm">
                          ({sym.symptom_kriol})
                        </span>
                      )}
                    </span>
                  </h3>

                  <p className="text-gray-700 mb-1">
                    <strong>Description:</strong>{" "}
                    {sym[lang]?.description || sym.en.description}
                  </p>
                  <p className="text-gray-700 mb-1">
                    <strong>Common Causes:</strong>{" "}
                    {sym[lang]?.common_causes || sym.en.common_causes}
                  </p>
                  <p className="text-gray-700">
                    <strong>Advice:</strong>{" "}
                    {sym[lang]?.advice || sym.en.advice}
                  </p>
                </div>
              );
            })
          ) : (
            <p className="text-gray-600">No symptoms found.</p>
          )}
        </section>

        {/* Section 3: What You Can Do Now */}
        <section>
          <h2 className="text-xl font-semibold text-gray-700 mb-2">
            🌿 What You Can Do Now
          </h2>
          <p className="text-gray-700 leading-relaxed">
            Rest well, stay hydrated, and monitor your symptoms. If your
            condition worsens or new symptoms appear, please visit the nearest
            clinic or hospital. Health advice is general — always seek a
            professional when unsure.
          </p>
        </section>
      </div>

      {/* Footer Buttons */}
      <div className="flex justify-between items-center mt-8">
        <button
          onClick={() => navigate(-1)}
          className="bg-gray-200 px-4 py-2 rounded-lg hover:bg-gray-300 text-gray-700 font-medium"
        >
          ← Back
        </button>

        <button
          onClick={handlePrint}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 shadow"
        >
          📄 Save as PDF
        </button>
      </div>
    </div>
  );
}
